WITH exploded AS (SELECT id, host, level, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) x AS key, attr_value) SELECT level, COUNT(*) FILTER (WHERE level = 'DEBUG') AS debug_rows, SORT_ARRAY(COLLECT_SET(host)) AS host_list, COUNT_IF(level = 'WARN') AS warn_events, SORT_ARRAY(COLLECT_SET(key)) AS key_list, COUNT(*) FILTER (WHERE level = 'WARN') AS warn_rows, SIZE(COLLECT_SET(key)) AS num_keys FROM exploded GROUP BY level;
